\label{lemma:substitution}
If we have derivation $\vcenter{\infer{Q}{P}}$,
then we have derivation $\vcenter{\infer{Q\sub{x}{v}}{P\sub{x}{v}}}$.

\label{lemma:universal}
If $\vdash \context{ \forall x. P }$ holds
 then, for all terms~$v$, $\vdash \context{ P\sub{x}{v} }$ holds.

\[
\begin{prooftree}
\vdash P\sub{x}{y}, \Gamma
\justifies
\vdash \forall x. P, \Gamma
\using
\mbox{where $y$ is fresh for $\forall x. P$ and all formulae in $\Gamma$}
\end{prooftree}
\]

A \textit{killing context} is a context defined by the following grammar.
\[
 \tcontext{} \Coloneqq \{\ \cdot\ \} \mid \tcontext{} \wwith \tcontext{} \mid \forall x. \tcontext{}
\mid \new x.\tcontext{}
\]
In the above, $\{\ \cdot\ \}$ is a hole into which any formula can be plugged. An $n$-ary killing context is a killing context in which $n$ holes appear.

\[
 \tcontext{} \Coloneqq \{\ \cdot\ \} \mid \tcontext{} \wwith \tcontext{} \mid \forall x. \tcontext{}
\mid \new x.\tcontext{}
\]

\label{lemma:kill-distribute}
For any killing context $\tcontext{}$, $\vdash \tcontext{\cunit, \hdots, \cunit}$ holds; and, assuming the free variables of $P$ are not bound by $\tcontext{}$,


we have derivation
\[
\infer[.]{
P \cpar \tcontext{Q_1, Q_2, \hdots Q_n}
}{
\tcontext{P \cpar Q_1, P \cpar Q_2, \hdots P \cpar Q_n}
}
\]

\[
\infer[.]{
P \cpar \tcontext{Q_1, Q_2, \hdots Q_n}
}{
\tcontext{P \cpar Q_1, P \cpar Q_2, \hdots P \cpar Q_n}
}
\]

~\label{lemma:medial}
Assume that $I$ is a finite subset of natural numbers, $P_i$ and $Q_i$ are formulae, for $i \in I$, and $\tcontext{}$ is a killing context. There exist killing contexts $\tcontextn{0}{}$ and $\tcontextn{1}{}$ and sets of natural numbers $J \subseteq I$ and $K \subseteq I$ such that the following derivation holds:
\[
\infer[.]{
\tcontext{ P_i \cseq Q_i \colon i \in I }
}{
\tcontextn{0}{ P_j \colon j \in J } \cseq
\tcontextn{1}{ Q_k \colon k \in K }
}
\]

\[
\infer[.]{
\tcontext{ P_i \cseq Q_i \colon i \in I }
}{
\tcontextn{0}{ P_j \colon j \in J } \cseq
\tcontextn{1}{ Q_k \colon k \in K }
}
\]

