\label{lemma:split-exists}
If $\vdash \exists x. P \cpar Q$, then there exist formulae $V_i$ and values $v_i$ such that $\vdash P\sub{x}{v_i} \cpar V_i$, where $1 \leq i \leq n$, and $n$-ary killing context $\tcontext{}$ such that $\vcenter{\infer{Q}{ \tcontext{V_1, V_2, \hdots, V_n}}}$
and if $\tcontext{}$ binds $y$ then $\nfv{y}{\left(\exists x . P\right)}$.

\label{lemma:split-plus}
If $\vdash \left( P \ooplus Q \right) \cpar R$, then there exist formulae $W_i$ such that either $\vdash P \cpar W_i$ or $\vdash Q \cpar W_i$ where $1 \leq i \leq n$, and $n$-ary killing context $\tcontext{}$ such that $\vcenter{\infer{R}{\tcontext{W_1, W_2, \hdots, W_n}}}$
and if $\tcontext{}$ binds $x$ then $\nfv{x}{\left(P \ooplus Q\right)}$.

\label{lemma:split-atoms}
The following statements hold, for any atom $\alpha$, where if $\tcontext{}$ binds $x$ then $\nfv{x}{\alpha}$.
\begin{itemize}
\item If $\vdash \co{\alpha} \cpar Q$, then there exist $n$-ary killing context $\tcontext{}$ such that 
$\vcenter{\infer{Q}{\tcontext{\alpha, \alpha, \hdots, \alpha}}}$.

\item If $\vdash \alpha \cpar Q$, then there exist $n$-ary killing context $\tcontext{}$ such that 
$\vcenter{\infer{Q}{\tcontext{\co{\alpha}, \co{\alpha}, \hdots, \co{\alpha}}}}$.
\end{itemize}

\label{lemma:invariant}
If $\vdash \context{T}$, then there exist formulae $U_i$ and substitutions $\sigma_i$, for $1 \leq i \leq n$, and $n$-ary killing context $\tcontext{}$ such that $\vdash T\sigma_i \cpar U_i$; and, for any formula $V$ there exist $W_i$ such that either $W_i = V\sigma_i \cpar U_i$ or $W_i = \cunit$ and the following holds:
$
\vcenter{
\infer[]{
 \context{V}
}{
 \tcontext{ W_1, W_2, \hdots, W_n }
}
}$.

